import java.util.*;
public class AhoCorasick {
    static final int ALPHA = 26;
    int[][] go; int[] fail, out; int size;
    AhoCorasick(int maxNodes) { go=new int[maxNodes][ALPHA]; fail=new int[maxNodes]; out=new int[maxNodes]; size=1; }
    int addPattern(String pat, int idx) {
        int cur=0;
        for (char c : pat.toCharArray()) {
            int ch=c-'a';
            if (go[cur][ch]==0) go[cur][ch]=size++;
            cur=go[cur][ch];
        }
        out[cur]|=(1<<idx); return size;
    }
    void buildFailLinks() {
        Queue<Integer> q=new LinkedList<>();
        for (int c=0;c<ALPHA;c++) if (go[0][c]!=0) q.add(go[0][c]);
        while (!q.isEmpty()) {
            int u=q.poll();
            for (int c=0;c<ALPHA;c++) {
                int v=go[u][c];
                if (v!=0) { fail[v]=go[fail[u]][c]; out[v]|=out[fail[v]]; q.add(v); }
                else go[u][c]=go[fail[u]][c];
            }
        }
    }
    void search(String text, String[] patterns) {
        int cur=0;
        for (int i=0;i<text.length();i++) {
            cur=go[cur][text.charAt(i)-'a'];
            if (out[cur]!=0) for (int j=0;j<patterns.length;j++)
                if ((out[cur]&(1<<j))!=0) System.out.println(patterns[j]+" at "+i);
        }
    }
}

